# 1. detect REMOTION beats by their beat sheet, not their folder:
def is_remotion(b):
    shot = b.get('shot') or {}
    return (str(shot.get('type','')).upper() == 'REMOTION'
            or bool(shot.get('remotion')))

# 2. does Root.tsx register the 916 sibling of this pattern?
def portrait_pattern(pattern, tsx):
    if pattern.endswith('916') and f'id="{pattern}"' in tsx:
        return pattern
    cand = f'{pattern}916'
    return cand if f'id="{cand}"' in tsx else None

# 3. rewire (per kept beat) — vertical uses this same block:
p916 = portrait_pattern(pattern, tsx)
if p916:
    b['shot']['remotion']['pattern'] = p916      # re-render portrait
else:
    onda_blocked.append((bid, pattern))         # add 916 or pantry

